package com.agendador.agenda;

public class Agenda {
    private Long idAgenda;
    private Long idUsuario;
    private Long idEmpreendedor;
    private String horarioAgenda;
    private String dataAgenda;
    private Boolean agendadoUsuario;
    private Boolean agendadoEmpreendedor;

    public Long getIdAgenda() {
        return idAgenda;
    }

    public void setIdAgenda(Long idAgenda) {
        this.idAgenda = idAgenda;
    }

    public Long getIdUsuario() {
        return idUsuario;
    }

    public void setIdUsuario(Long idUsuario) {
        this.idUsuario = idUsuario;
    }

    public Long getIdEmpreendedor() {
        return idEmpreendedor;
    }

    public void setIdEmpreendedor(Long idEmpreendedor) {
        this.idEmpreendedor = idEmpreendedor;
    }

    public String getHorarioAgenda() {
        return horarioAgenda;
    }

    public void setHorarioAgenda(String horarioAgenda) {
        this.horarioAgenda = horarioAgenda;
    }

    public String getDataAgenda() {
        return dataAgenda;
    }

    public void setDataAgenda(String dataAgenda) {
        this.dataAgenda = dataAgenda;
    }

    public Boolean getAgendadoUsuario() {
        return agendadoUsuario;
    }

    public void setAgendadoUsuario(Boolean agendadoUsuario) {
        this.agendadoUsuario = agendadoUsuario;
    }

    public Boolean getAgendadoEmpreendedor() {
        return agendadoEmpreendedor;
    }

    public void setAgendadoEmpreendedor(Boolean agendadoEmpreendedor) {
        this.agendadoEmpreendedor = agendadoEmpreendedor;
    }
}

package com.agendador.agenda;

import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.responses.ApiResponse;
import io.swagger.v3.oas.annotations.responses.ApiResponses;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

@RestController
@RequestMapping("/agendas")
@Tag(name = "Agendas", description = "Operacoes de insercao, consulta, edicao e delecao da tabela agenda")
public class AgendaController {
    private final AgendaService agendaService;

    public AgendaController(AgendaService agendaService) {
        this.agendaService = agendaService;
    }

    @PostMapping
    @Operation(summary = "Inserir agenda")
    @ApiResponses({
            @ApiResponse(responseCode = "201", description = "Agenda inserida com sucesso"),
            @ApiResponse(responseCode = "400", description = "Dados invalidos")
    })
    public ResponseEntity<Agenda> inserir(@Valid @RequestBody AgendaRequest request) {
        Agenda agenda = agendaService.inserir(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(agenda);
    }

    @GetMapping
    @Operation(summary = "Listar agendas")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Lista retornada com sucesso")
    })
    public List<Agenda> listar() {
        return agendaService.listar();
    }

    @GetMapping("/{idAgenda}")
    @Operation(summary = "Buscar agenda por id")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Agenda encontrada"),
            @ApiResponse(responseCode = "404", description = "Agenda nao encontrada")
    })
    public Agenda buscarPorId(@PathVariable Long idAgenda) {
        return agendaService.buscarPorId(idAgenda);
    }

    @PutMapping("/{idAgenda}")
    @Operation(summary = "Editar agenda por id")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Agenda atualizada com sucesso"),
            @ApiResponse(responseCode = "400", description = "Dados invalidos"),
            @ApiResponse(responseCode = "404", description = "Agenda nao encontrada")
    })
    public Agenda atualizar(@PathVariable Long idAgenda, @Valid @RequestBody AgendaRequest request) {
        return agendaService.atualizar(idAgenda, request);
    }

    @DeleteMapping("/{idAgenda}")
    @Operation(summary = "Deletar agenda por id")
    @ApiResponses({
            @ApiResponse(responseCode = "204", description = "Agenda removida com sucesso"),
            @ApiResponse(responseCode = "404", description = "Agenda nao encontrada")
    })
    public ResponseEntity<Void> deletar(@PathVariable Long idAgenda) {
        agendaService.deletar(idAgenda);
        return ResponseEntity.noContent().build();
    }
}

package com.agendador.agenda;

import org.springframework.stereotype.Repository;

import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;

@Repository
public class AgendaRepository {
    private final DataSource dataSource;

    public AgendaRepository(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    public Agenda inserir(AgendaRequest request) {
        String sql = "INSERT INTO agenda (idusuario, idempreendedor, horario_agenda, data_agenda, agendado_usuario, agendado_empreendedor) "
                + "VALUES (?, ?, ?, ?, ?, ?) "
                + "RETURNING idagenda, idusuario, idempreendedor, horario_agenda, data_agenda, agendado_usuario, agendado_empreendedor";
        Connection conn = null;
        PreparedStatement stmt = null;
        ResultSet rs = null;
        try {
            conn = dataSource.getConnection();
            stmt = conn.prepareStatement(sql);
            stmt.setLong(1, request.getIdUsuario());
            stmt.setLong(2, request.getIdEmpreendedor());
            stmt.setString(3, request.getHorarioAgenda());
            stmt.setString(4, request.getDataAgenda());
            stmt.setBoolean(5, request.getAgendadoUsuario());
            stmt.setBoolean(6, request.getAgendadoEmpreendedor());
            rs = stmt.executeQuery();
            if (rs.next()) {
                return mapAgenda(rs);
            }
            throw new IllegalStateException("Insercao nao retornou agenda");
        } catch (SQLException e) {
            throw new RuntimeException("Erro ao inserir agenda", e);
        } finally {
            closeQuietly(rs);
            closeQuietly(stmt);
            closeQuietly(conn);
        }
    }

    public List<Agenda> listar() {
        String sql = "SELECT idagenda, idusuario, idempreendedor, horario_agenda, data_agenda, agendado_usuario, agendado_empreendedor "
                + "FROM agenda ORDER BY idagenda";
        Connection conn = null;
        PreparedStatement stmt = null;
        ResultSet rs = null;
        List<Agenda> agendas = new ArrayList<Agenda>();
        try {
            conn = dataSource.getConnection();
            stmt = conn.prepareStatement(sql);
            rs = stmt.executeQuery();
            while (rs.next()) {
                agendas.add(mapAgenda(rs));
            }
            return agendas;
        } catch (SQLException e) {
            throw new RuntimeException("Erro ao listar agendas", e);
        } finally {
            closeQuietly(rs);
            closeQuietly(stmt);
            closeQuietly(conn);
        }
    }

    public Agenda buscarPorId(Long idAgenda) {
        String sql = "SELECT idagenda, idusuario, idempreendedor, horario_agenda, data_agenda, agendado_usuario, agendado_empreendedor "
                + "FROM agenda WHERE idagenda = ?";
        Connection conn = null;
        PreparedStatement stmt = null;
        ResultSet rs = null;
        try {
            conn = dataSource.getConnection();
            stmt = conn.prepareStatement(sql);
            stmt.setLong(1, idAgenda);
            rs = stmt.executeQuery();
            if (rs.next()) {
                return mapAgenda(rs);
            }
            return null;
        } catch (SQLException e) {
            throw new RuntimeException("Erro ao buscar agenda por id", e);
        } finally {
            closeQuietly(rs);
            closeQuietly(stmt);
            closeQuietly(conn);
        }
    }

    public Agenda atualizar(Long idAgenda, AgendaRequest request) {
        String sql = "UPDATE agenda SET idusuario = ?, idempreendedor = ?, horario_agenda = ?, data_agenda = ?, "
                + "agendado_usuario = ?, agendado_empreendedor = ? WHERE idagenda = ?";
        Connection conn = null;
        PreparedStatement stmt = null;
        try {
            conn = dataSource.getConnection();
            stmt = conn.prepareStatement(sql);
            stmt.setLong(1, request.getIdUsuario());
            stmt.setLong(2, request.getIdEmpreendedor());
            stmt.setString(3, request.getHorarioAgenda());
            stmt.setString(4, request.getDataAgenda());
            stmt.setBoolean(5, request.getAgendadoUsuario());
            stmt.setBoolean(6, request.getAgendadoEmpreendedor());
            stmt.setLong(7, idAgenda);
            int linhasAfetadas = stmt.executeUpdate();
            if (linhasAfetadas == 0) {
                return null;
            }
            return buscarPorId(idAgenda);
        } catch (SQLException e) {
            throw new RuntimeException("Erro ao atualizar agenda", e);
        } finally {
            closeQuietly(stmt);
            closeQuietly(conn);
        }
    }

    public boolean deletar(Long idAgenda) {
        String sql = "DELETE FROM agenda WHERE idagenda = ?";
        Connection conn = null;
        PreparedStatement stmt = null;
        try {
            conn = dataSource.getConnection();
            stmt = conn.prepareStatement(sql);
            stmt.setLong(1, idAgenda);
            return stmt.executeUpdate() > 0;
        } catch (SQLException e) {
            throw new RuntimeException("Erro ao deletar agenda", e);
        } finally {
            closeQuietly(stmt);
            closeQuietly(conn);
        }
    }

    private Agenda mapAgenda(ResultSet rs) throws SQLException {
        Agenda agenda = new Agenda();
        agenda.setIdAgenda(rs.getLong("idagenda"));
        agenda.setIdUsuario(rs.getLong("idusuario"));
        agenda.setIdEmpreendedor(rs.getLong("idempreendedor"));
        agenda.setHorarioAgenda(rs.getString("horario_agenda"));
        agenda.setDataAgenda(rs.getString("data_agenda"));
        agenda.setAgendadoUsuario(rs.getBoolean("agendado_usuario"));
        agenda.setAgendadoEmpreendedor(rs.getBoolean("agendado_empreendedor"));
        return agenda;
    }

    private void closeQuietly(ResultSet rs) {
        if (rs == null) {
            return;
        }
        try {
            rs.close();
        } catch (SQLException ignored) {
            // Intencional: fechamento seguro sem sobrescrever erro principal.
        }
    }

    private void closeQuietly(PreparedStatement stmt) {
        if (stmt == null) {
            return;
        }
        try {
            stmt.close();
        } catch (SQLException ignored) {
            // Intencional: fechamento seguro sem sobrescrever erro principal.
        }
    }

    private void closeQuietly(Connection conn) {
        if (conn == null) {
            return;
        }
        try {
            conn.close();
        } catch (SQLException ignored) {
            // Intencional: fechamento seguro sem sobrescrever erro principal.
        }
    }
}

