package com.agendador.usuario;

import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

@Service
public class UsuarioService {
    private final UsuarioRepository usuarioRepository;

    public UsuarioService(UsuarioRepository usuarioRepository) {
        this.usuarioRepository = usuarioRepository;
    }

    public Usuario inserir(UsuarioRequest request) {
        return usuarioRepository.inserir(request);
    }

    public Usuario atualizar(Long idUsuario, UsuarioRequest request) {
        Usuario usuarioAtualizado = usuarioRepository.atualizar(idUsuario, request);
        if (usuarioAtualizado == null) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Usuario nao encontrado");
        }
        return usuarioAtualizado;
    }

    public void deletar(Long idUsuario) {
        boolean deletado = usuarioRepository.deletar(idUsuario);
        if (!deletado) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Usuario nao encontrado");
        }
    }
}

package com.agendador.view;

import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.button.ButtonVariant;
import com.vaadin.flow.component.html.Div;
import com.vaadin.flow.component.html.H2;
import com.vaadin.flow.component.html.H3;
import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.router.BeforeEnterEvent;
import com.vaadin.flow.router.BeforeEnterObserver;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;
import com.vaadin.flow.server.VaadinSession;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.format.TextStyle;
import java.util.Locale;

@Route("calendario")
@PageTitle("Calendario")
public class CalendarioView extends VerticalLayout implements BeforeEnterObserver {

    private static final Locale LOCALE_PT_BR = new Locale("pt", "BR");

    public CalendarioView() {
        LocalDate hoje = LocalDate.now();
        YearMonth mesAtual = YearMonth.from(hoje);

        setSizeFull();
        setPadding(false);
        setSpacing(false);
        getStyle().set("background", "linear-gradient(180deg, #f4f8ff 0%, #ffffff 100%)");

        HorizontalLayout layout = new HorizontalLayout();
        layout.setSizeFull();
        layout.setPadding(false);
        layout.setSpacing(false);

        Div calendarioCard = buildCalendarioCard(mesAtual, hoje);
        layout.add(buildSidebar(), calendarioCard);
        layout.expand(calendarioCard);

        add(layout);
    }

    @Override
    public void beforeEnter(BeforeEnterEvent event) {
        Object autenticado = VaadinSession.getCurrent().getAttribute("adminAutenticado");
        if (!(autenticado instanceof Boolean) || !((Boolean) autenticado)) {
            event.rerouteTo("login");
        }
    }

    private Div buildSidebar() {
        Div sidebar = new Div();
        sidebar.getStyle().set("width", "220px");
        sidebar.getStyle().set("background", "linear-gradient(160deg,#0b4ebd,#073683)");
        sidebar.getStyle().set("color", "#ffffff");
        sidebar.getStyle().set("padding", "24px 16px");
        sidebar.getStyle().set("box-sizing", "border-box");

        H3 title = new H3("Agenda");
        title.getStyle().set("margin", "0 0 20px 0");

        sidebar.add(title,
                menuItem("Calendario", true),
                menuItem("Tarefas", false),
                menuItem("Contatos", false),
                menuItem("Configuracoes", false));
        return sidebar;
    }

    private Div menuItem(String label, boolean ativo) {
        Div item = new Div();
        item.setText(label);
        item.getStyle().set("padding", "10px 12px");
        item.getStyle().set("border-radius", "10px");
        item.getStyle().set("margin-bottom", "8px");
        item.getStyle().set("font-weight", "600");
        if (ativo) {
            item.getStyle().set("background", "rgba(255,255,255,0.14)");
        }
        return item;
    }

    private Div buildCalendarioCard(YearMonth mesAtual, LocalDate hoje) {
        Div card = new Div();
        card.getStyle().set("flex", "1");
        card.getStyle().set("margin", "12px");
        card.getStyle().set("background", "#ffffff");
        card.getStyle().set("border-radius", "18px");
        card.getStyle().set("padding", "20px");
        card.getStyle().set("box-shadow", "0 10px 35px rgba(24,56,120,0.12)");

        H2 tituloPagina = new H2("Calendario");
        tituloPagina.getStyle().set("margin", "0 0 8px 0");

        Button sair = new Button("Sair");
        sair.addThemeVariants(ButtonVariant.LUMO_TERTIARY_INLINE);
        sair.addClickListener(event -> {
            VaadinSession.getCurrent().setAttribute("adminAutenticado", false);
            getUI().ifPresent(ui -> ui.navigate("login"));
        });

        HorizontalLayout topo = new HorizontalLayout(tituloPagina, sair);
        topo.setWidthFull();
        topo.setPadding(false);
        topo.setSpacing(true);
        topo.setJustifyContentMode(JustifyContentMode.BETWEEN);
        topo.setAlignItems(Alignment.CENTER);

        H3 tituloMes = new H3(formatarMesAno(mesAtual));
        tituloMes.getStyle().set("margin", "0 0 16px 0");

        HorizontalLayout cabecalhoDias = new HorizontalLayout();
        cabecalhoDias.setWidthFull();
        cabecalhoDias.setPadding(false);
        cabecalhoDias.setSpacing(false);
        String[] dias = {"Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sab"};
        for (String dia : dias) {
            Div d = new Div();
            d.setText(dia);
            d.getStyle().set("flex", "1");
            d.getStyle().set("text-align", "center");
            d.getStyle().set("font-weight", "600");
            d.getStyle().set("color", "#5f6f91");
            d.getStyle().set("padding", "6px 0");
            cabecalhoDias.add(d);
        }

        Div grade = new Div();
        grade.getStyle().set("display", "grid");
        grade.getStyle().set("grid-template-columns", "repeat(7, minmax(0, 1fr))");
        grade.getStyle().set("gap", "8px");

        int deslocamento = converterParaInicioDomingo(mesAtual.atDay(1).getDayOfWeek());
        int diasNoMes = mesAtual.lengthOfMonth();
        int diasMesAnterior = mesAtual.minusMonths(1).lengthOfMonth();

        for (int i = 0; i < 42; i++) {
            Div celula = new Div();
            celula.getStyle().set("min-height", "64px");
            celula.getStyle().set("border", "1px solid #e7ecf7");
            celula.getStyle().set("border-radius", "10px");
            celula.getStyle().set("display", "flex");
            celula.getStyle().set("align-items", "flex-start");
            celula.getStyle().set("justify-content", "flex-start");
            celula.getStyle().set("padding", "10px");

            int numeroDia;
            boolean outroMes = false;
            if (i < deslocamento) {
                numeroDia = (diasMesAnterior - deslocamento + 1) + i;
                outroMes = true;
            } else if (i >= deslocamento + diasNoMes) {
                numeroDia = i - (deslocamento + diasNoMes) + 1;
                outroMes = true;
            } else {
                numeroDia = i - deslocamento + 1;
            }

            Div textoDia = new Div();
            textoDia.setText(String.valueOf(numeroDia));
            textoDia.getStyle().set("font-weight", "600");

            if (outroMes) {
                textoDia.getStyle().set("color", "#b5c1d8");
            } else {
                textoDia.getStyle().set("color", "#0d2149");
            }

            if (!outroMes && numeroDia == hoje.getDayOfMonth()) {
                textoDia.getStyle().set("background", "#0b5fff");
                textoDia.getStyle().set("color", "#ffffff");
                textoDia.getStyle().set("width", "32px");
                textoDia.getStyle().set("height", "32px");
                textoDia.getStyle().set("border-radius", "50%");
                textoDia.getStyle().set("display", "inline-flex");
                textoDia.getStyle().set("align-items", "center");
                textoDia.getStyle().set("justify-content", "center");
            }

            celula.add(textoDia);
            grade.add(celula);
        }

        card.add(topo, tituloMes, cabecalhoDias, grade);
        return card;
    }

    private String formatarMesAno(YearMonth mesAtual) {
        String mes = mesAtual.getMonth().getDisplayName(TextStyle.FULL, LOCALE_PT_BR);
        String mesCapitalizado = Character.toUpperCase(mes.charAt(0)) + mes.substring(1);
        return mesCapitalizado + " " + mesAtual.getYear();
    }

    private int converterParaInicioDomingo(DayOfWeek dayOfWeek) {
        return dayOfWeek.getValue() % 7;
    }
}

package com.agendador.view;

import com.agendador.empreendedor.EmpreendedorRequest;
import com.agendador.empreendedor.EmpreendedorService;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.button.ButtonVariant;
import com.vaadin.flow.component.formlayout.FormLayout;
import com.vaadin.flow.component.html.Div;
import com.vaadin.flow.component.html.H2;
import com.vaadin.flow.component.html.H4;
import com.vaadin.flow.component.html.Paragraph;
import com.vaadin.flow.component.icon.VaadinIcon;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.notification.NotificationVariant;
import com.vaadin.flow.component.orderedlayout.FlexComponent;
import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.textfield.PasswordField;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.data.value.ValueChangeMode;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;
import org.springframework.web.server.ResponseStatusException;

@Route("empreendedor/cadastro")
@PageTitle("Cadastro de Empreendedor")
public class EmpreendedorView extends VerticalLayout {

    private final EmpreendedorService empreendedorService;

    public EmpreendedorView(EmpreendedorService empreendedorService) {
        this.empreendedorService = empreendedorService;

        setSizeFull();
        setPadding(true);
        setSpacing(true);
        setAlignItems(Alignment.CENTER);
        getStyle().set("background", "#f4f8ff");

        HorizontalLayout card = new HorizontalLayout();
        card.setWidthFull();
        card.setMaxWidth("1200px");
        card.setPadding(false);
        card.setSpacing(false);
        card.getStyle().set("background", "white");
        card.getStyle().set("border-radius", "20px");
        card.getStyle().set("box-shadow", "0 10px 40px rgba(24, 56, 120, 0.15)");
        card.getStyle().set("overflow", "hidden");
        card.getStyle().set("flex-wrap", "wrap");

        card.add(buildLeftPanel(), buildFormPanel());
        add(card);
    }

    private Div buildLeftPanel() {
        Div leftPanel = new Div();
        leftPanel.getStyle().set("background", "linear-gradient(160deg,#0050d7,#003d99)");
        leftPanel.getStyle().set("color", "white");
        leftPanel.getStyle().set("padding", "48px");
        leftPanel.getStyle().set("min-width", "320px");
        leftPanel.getStyle().set("flex", "1 1 320px");

        H2 title = new H2("Cadastre um novo empreendedor");
        title.getStyle().set("margin-top", "0");

        Paragraph subtitle = new Paragraph("Preencha os dados ao lado para criar um novo empreendedor no sistema.");
        subtitle.getStyle().set("opacity", "0.9");

        leftPanel.add(title, subtitle);
        return leftPanel;
    }

    private VerticalLayout buildFormPanel() {
        VerticalLayout formPanel = new VerticalLayout();
        formPanel.setSpacing(true);
        formPanel.setPadding(true);
        formPanel.getStyle().set("padding", "40px");
        formPanel.getStyle().set("min-width", "320px");
        formPanel.getStyle().set("flex", "2 1 560px");

        H4 section = new H4("EMPREENDEDORES");
        section.getStyle().set("color", "#0b5fff");
        section.getStyle().set("margin", "0");

        H2 title = new H2("Cadastro de Empreendedor");
        title.getStyle().set("margin", "0");

        Paragraph subtitle = new Paragraph("Informe os dados abaixo para cadastrar um novo empreendedor.");
        subtitle.getStyle().set("color", "#5f6f91");

        FormLayout form = new FormLayout();
        form.setWidthFull();
        form.setResponsiveSteps(
                new FormLayout.ResponsiveStep("0", 1),
                new FormLayout.ResponsiveStep("900px", 1)
        );

        TextField nome = new TextField("Nome do Empreendedor");
        nome.setPlaceholder("Digite o nome do empreendedor");
        nome.setPrefixComponent(VaadinIcon.USER.create());
        nome.setWidthFull();

        TextField endereco = new TextField("Endereco");
        endereco.setPlaceholder("Digite o endereco do empreendedor");
        endereco.setPrefixComponent(VaadinIcon.HOME.create());
        endereco.setWidthFull();

        TextField celular = new TextField("Celular");
        celular.setPlaceholder("Digite o celular do empreendedor");
        celular.setPrefixComponent(VaadinIcon.MOBILE.create());
        celular.setWidthFull();
        celular.setValueChangeMode(ValueChangeMode.EAGER);
        celular.addValueChangeListener(event -> aplicarMascaraCelular(celular));

        TextField usuario = new TextField("Usuario");
        usuario.setPlaceholder("Digite o usuario de acesso");
        usuario.setPrefixComponent(VaadinIcon.USER_CARD.create());
        usuario.setWidthFull();

        PasswordField senha = new PasswordField("Senha");
        senha.setPlaceholder("Digite a senha");
        senha.setWidthFull();

        form.add(nome, endereco, celular, usuario, senha);

        Button salvar = new Button("Salvar Empreendedor", VaadinIcon.CHECK.create());
        salvar.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
        salvar.addClickListener(event -> salvarEmpreendedor(nome, endereco, celular, usuario, senha));

        Button cancelar = new Button("Cancelar", VaadinIcon.CLOSE_SMALL.create());
        cancelar.addThemeVariants(ButtonVariant.LUMO_TERTIARY);
        cancelar.addClickListener(event -> {
            nome.clear();
            endereco.clear();
            celular.clear();
            usuario.clear();
            senha.clear();
        });

        HorizontalLayout actions = new HorizontalLayout(cancelar, salvar);
        actions.setWidthFull();
        actions.setJustifyContentMode(FlexComponent.JustifyContentMode.END);
        actions.getStyle().set("margin-top", "8px");

        formPanel.add(section, title, subtitle, form, actions);
        return formPanel;
    }

    private void salvarEmpreendedor(TextField nome, TextField endereco, TextField celular,
                                    TextField usuario, PasswordField senha) {
        if (isBlank(nome.getValue()) || isBlank(endereco.getValue()) || isBlank(celular.getValue())
                || isBlank(usuario.getValue()) || isBlank(senha.getValue())) {
            Notification notification = Notification.show("Preencha os campos obrigatorios.");
            notification.addThemeVariants(NotificationVariant.LUMO_ERROR);
            return;
        }

        EmpreendedorRequest request = new EmpreendedorRequest();
        request.setNomeEmpreendedor(nome.getValue());
        request.setEnderecoEmpreendedor(endereco.getValue());
        request.setCelularEmpreendedor(celular.getValue().replaceAll("\\D", ""));
        request.setUsuarioEmpreendedor(usuario.getValue());
        request.setSenhaEmpreendedor(senha.getValue());

        try {
            empreendedorService.inserir(request);
            Notification notification = Notification.show("Empreendedor salvo com sucesso.");
            notification.addThemeVariants(NotificationVariant.LUMO_SUCCESS);
            nome.clear();
            endereco.clear();
            celular.clear();
            usuario.clear();
            senha.clear();
        } catch (ResponseStatusException ex) {
            Notification notification = Notification.show(ex.getReason() != null ? ex.getReason() : "Erro ao salvar empreendedor.");
            notification.addThemeVariants(NotificationVariant.LUMO_ERROR);
        } catch (Exception ex) {
            Throwable causa = ex.getCause() != null ? ex.getCause() : ex;
            String mensagem = causa.getMessage() != null ? causa.getMessage() : "Erro ao salvar empreendedor.";
            Notification notification = Notification.show("Erro ao salvar empreendedor: " + mensagem);
            notification.addThemeVariants(NotificationVariant.LUMO_ERROR);
        }
    }

    private void aplicarMascaraCelular(TextField celularField) {
        String somenteDigitos = celularField.getValue().replaceAll("\\D", "");
        if (somenteDigitos.length() > 11) {
            somenteDigitos = somenteDigitos.substring(0, 11);
        }

        StringBuilder mascarado = new StringBuilder();
        for (int i = 0; i < somenteDigitos.length(); i++) {
            if (i == 0) {
                mascarado.append('(');
            }
            if (i == 2) {
                mascarado.append(") ");
            }
            if (i == 7) {
                mascarado.append('-');
            }
            mascarado.append(somenteDigitos.charAt(i));
        }

        String valorFormatado = mascarado.toString();
        if (!valorFormatado.equals(celularField.getValue())) {
            celularField.setValue(valorFormatado);
        }
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }
}

